BattlePreview.mountBag=({use,close})=>{
 const menu=document.createElement('section');menu.id='bag-menu';menu.className='bag-menu';menu.hidden=true;menu.setAttribute('aria-label','전투 가방');document.getElementById('move-menu').after(menu);let state,selecting=false;
 function button(title,description,icon,onClick,disabled=false){const b=document.createElement('button');b.type='button';b.className='bag-item';const glyph=document.createElement('span'),text=document.createElement('span'),name=document.createElement('strong'),note=document.createElement('small');glyph.className='fluent-emoji';glyph.setAttribute('aria-hidden','true');glyph.textContent=icon;name.textContent=title;note.textContent=description;text.append(name,note);b.append(glyph,text);b.disabled=disabled;b.addEventListener('click',onClick);return b;}
 function render(){if(!state)return;const title=document.createElement('strong'),list=document.createElement('div'),hint=document.createElement('p'),back=document.createElement('button'),moves=Craft.Moves.forWeapon(BattlePreview.weapon);title.textContent=selecting?'어느 기술을 충전할까?':'어떤 아이템을 쓸까?';list.className='bag-grid';hint.textContent='아이템을 사용하면 한 턴이 지나고 상대가 행동해.';hint.className='bag-hint';back.type='button';back.className='move-back';back.textContent=selecting?'가방으로':'돌아가기';back.addEventListener('click',()=>{if(selecting){selecting=false;render();focus();}else close();});
  if(selecting){moves.forEach((move,index)=>{const reason=Craft.Items.reason(state,{id:'charge',index},moves,Craft.Conditions);list.append(button(move.name,'PP '+state.pp[index]+' / '+move.pp+(reason?' · '+reason:' · PP 5 회복'),'⚡',()=>use('item:charge:'+index),!!reason));});}
  else for(const[id,item]of Object.entries(Craft.Items.definitions)){const n=Craft.Items.count(state,id),reason=id==='charge'?(moves.every((m,index)=>!!Craft.Items.reason(state,{id,index},moves,Craft.Conditions))?'충전할 기술이 없어.':''):Craft.Items.reason(state,{id},moves,Craft.Conditions);list.append(button(item.name+' ×'+n,n?(reason||item.description):'모두 사용했어',item.icon,()=>{if(id==='charge'){selecting=true;render();focus();}else use('item:'+id);},!n||!!reason));}
  menu.replaceChildren(title,list,hint,back);
 }
 function focus(){(menu.querySelector('button:not(:disabled)')||menu.querySelector('button')).focus({preventScroll:true});}
 menu.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(selecting){selecting=false;render();focus();}else close();return;}const offsets={ArrowRight:1,ArrowLeft:-1,ArrowDown:2,ArrowUp:-2};if(e.key in offsets){const buttons=[...menu.querySelectorAll('button:not(:disabled)')],index=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(index+offsets[e.key]+buttons.length*2)%buttons.length]?.focus();}});
 return{open(s){state=s;selecting=false;menu.hidden=false;render();focus();},hide(){menu.hidden=true;selecting=false;},update(s){state=s;if(!menu.hidden)render();},isOpen:()=>!menu.hidden};
};
